for (int tile_base = 0; tile_base < N; tile_base += TILE) {
    load_tile: for (int i = 0; i < TILE; ++i) {
#pragma HLS PIPELINE II=1
        if (tile_base + i < N) tile[i] = in[tile_base + i];
    }

    compute_tile: for (int i = 0; i < TILE; ++i) {
#pragma HLS PIPELINE II=1
        if (tile_base + i < N) out_tile[i] = f(tile[i]);
    }

    store_tile: for (int i = 0; i < TILE; ++i) {
#pragma HLS PIPELINE II=1
        if (tile_base + i < N) out[tile_base + i] = out_tile[i];
    }
}

data_t tile[TILE];
data_t out_tile[TILE];
#pragma HLS ARRAY_PARTITION variable=tile cyclic factor=UNROLL_FACTOR dim=1
#pragma HLS ARRAY_PARTITION variable=out_tile cyclic factor=UNROLL_FACTOR dim=1

for (int tile_base = 0; tile_base < N; tile_base += TILE) {
    load_tile: for (int i = 0; i < TILE; ++i) {
#pragma HLS PIPELINE II=1
        int idx = tile_base + i;
        if (idx < N) tile[i] = in[idx];
    }

    compute_tile: for (int i = 0; i < TILE; i += UNROLL_FACTOR) {
#pragma HLS PIPELINE II=1
        lane_loop: for (int lane = 0; lane < UNROLL_FACTOR; ++lane) {
#pragma HLS UNROLL
            int local_idx = i + lane;
            int global_idx = tile_base + local_idx;
            if (local_idx < TILE && global_idx < N) out_tile[local_idx] = f(tile[local_idx]);
        }
    }

    store_tile: for (int i = 0; i < TILE; ++i) {
#pragma HLS PIPELINE II=1
        int idx = tile_base + i;
        if (idx < N) out[idx] = out_tile[i];
    }
}

